-- ============================================================
-- Regulatory Tracker
-- Migration 024
-- ============================================================
-- Sustainability teams do not lose sleep over the arithmetic. They lose sleep
-- over not knowing that a deadline moved. Between the EU Omnibus package, the
-- GHG Protocol/ISO consolidation, SBTi V2 and the collapse of the US federal
-- rule, nearly every date a practitioner memorised in 2024 is now wrong.
--
-- This module is the reference layer for that: what each regime is, where it
-- stands, what happens next, and - the part that makes it usable rather than
-- decorative - how confident anyone should be in each answer.
--
--   regulatory_items    - one tracked regime, standard or rule
--   regulatory_updates  - dated activity feed against those items
--
-- ─── Why confidence and last_verified are NOT NULL ──────────────────────────
--
-- CLAUDE.md forbids fabricating regulatory content, and a tracker is nothing
-- BUT regulatory content, so the schema is built so an unsourced claim cannot
-- be stored quietly. Every item must carry a confidence rating, a
-- last_verified date, and at least one source with a URL - enforced by CHECK
-- constraints, not convention. An entry nobody has re-checked in months
-- announces that fact in the UI rather than looking as authoritative as one
-- confirmed this morning.
--
-- The confidence vocabulary is deliberately the same one the reference
-- trackers in this field use:
--   confirmed - the official published text says this
--   high      - an official announcement or agreed political text says this
--   medium    - credible secondary reporting, no primary text read
--   low       - commentary or speculation; directionally useful only
--
-- ─── What this module deliberately does NOT do ──────────────────────────────
--
-- It does not tell a company whether a regime applies to it, and it does not
-- compute a compliance status. Both would require legal judgement about a
-- specific entity's facts, which this platform is not positioned to give and
-- which would be the fastest possible way to turn a helpful reference into a
-- liability. Scope thresholds are stated as published; the reader decides.
--
-- Content is data, not code: every field below can be corrected by an UPDATE
-- without a release, which is the point. Seed content was researched on
-- 2026-09-04 and every row carries its sources.
--
-- RE-RUNNABLE.
-- ============================================================

CREATE TABLE IF NOT EXISTS regulatory_items (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Stable short code. The natural key the seed upserts on, so a re-run
  -- corrects an existing row rather than duplicating it.
  code                VARCHAR(40) NOT NULL UNIQUE,
  name                TEXT NOT NULL,

  category            VARCHAR(30) NOT NULL
                      CHECK (category IN ('ghg_accounting', 'eu', 'us', 'other')),
  jurisdiction        TEXT NOT NULL,
  topics              TEXT[] NOT NULL DEFAULT '{}',

  -- Where the instrument sits in its own lifecycle. Kept coarse on purpose:
  -- finer stages differ per jurisdiction and would not compare across them.
  stage               VARCHAR(30) NOT NULL CHECK (stage IN (
                        'drafting', 'consultation_open', 'consultation_closed',
                        'proposed', 'in_negotiation', 'adopted', 'finalised',
                        'in_force', 'applying', 'stayed', 'enjoined',
                        'vacated', 'repealed', 'withdrawn')),

  status_summary      TEXT NOT NULL,
  key_points          JSONB NOT NULL DEFAULT '[]'::jsonb,

  next_milestone      TEXT,
  next_milestone_date DATE,
  next_milestone_note TEXT,

  confidence          VARCHAR(20) NOT NULL
                      CHECK (confidence IN ('confirmed', 'high', 'medium', 'low')),
  confidence_note     TEXT,

  -- At least one source, each with a url. A claim with no source is not
  -- storable - that is the whole guardrail.
  sources             JSONB NOT NULL,
  last_verified       DATE NOT NULL,

  display_order       INTEGER NOT NULL DEFAULT 0,
  is_active           BOOLEAN NOT NULL DEFAULT TRUE,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'regulatory_items_sources_nonempty') THEN
    ALTER TABLE regulatory_items ADD CONSTRAINT regulatory_items_sources_nonempty
      CHECK (jsonb_typeof(sources) = 'array' AND jsonb_array_length(sources) > 0);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'regulatory_items_key_points_array') THEN
    ALTER TABLE regulatory_items ADD CONSTRAINT regulatory_items_key_points_array
      CHECK (jsonb_typeof(key_points) = 'array');
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_regulatory_items_category
  ON regulatory_items(category, display_order) WHERE is_active;
CREATE INDEX IF NOT EXISTS idx_regulatory_items_milestone
  ON regulatory_items(next_milestone_date) WHERE is_active AND next_milestone_date IS NOT NULL;

COMMENT ON TABLE regulatory_items IS
  'Reference catalog of tracked ESG regimes, standards and rules. Content is data so it can be corrected by UPDATE without a release. Every row must carry a confidence rating, a last_verified date and at least one source.';
COMMENT ON COLUMN regulatory_items.confidence IS
  'confirmed = official published text; high = official announcement or agreed political text; medium = credible secondary reporting; low = commentary or speculation.';
COMMENT ON COLUMN regulatory_items.last_verified IS
  'When a human last checked this row against its sources. Surfaced in the UI so a stale entry cannot masquerade as a fresh one.';
COMMENT ON COLUMN regulatory_items.next_milestone_date IS
  'NULL is meaningful and common: it means no date has been announced, which is different from a date that is unknown to us.';

-- ─── Dated activity feed ─────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS regulatory_updates (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  item_code      VARCHAR(40) NOT NULL REFERENCES regulatory_items(code) ON DELETE CASCADE,
  update_date    DATE NOT NULL,
  headline       TEXT NOT NULL,
  detail         TEXT,
  source_url     TEXT NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (item_code, update_date, headline)
);

CREATE INDEX IF NOT EXISTS idx_regulatory_updates_date
  ON regulatory_updates(update_date DESC);

COMMENT ON TABLE regulatory_updates IS
  'Dated "what changed" feed. source_url is NOT NULL: an undated, unsourced update is a rumour, and this table will not store one.';

-- ─── Reference-table RLS, following migration 013 ────────────────────────────

ALTER TABLE regulatory_items   ENABLE ROW LEVEL SECURITY;
ALTER TABLE regulatory_updates ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "regulatory_items_read_authenticated" ON regulatory_items;
CREATE POLICY "regulatory_items_read_authenticated" ON regulatory_items
  FOR SELECT TO authenticated USING (TRUE);

DROP POLICY IF EXISTS "regulatory_updates_read_authenticated" ON regulatory_updates;
CREATE POLICY "regulatory_updates_read_authenticated" ON regulatory_updates
  FOR SELECT TO authenticated USING (TRUE);

GRANT SELECT ON regulatory_items, regulatory_updates TO authenticated;
-- No write policies: service role or migration only.

-- ─── Seed ────────────────────────────────────────────────────────────────────
-- Researched 2026-09-04. ON CONFLICT DO UPDATE so a re-run corrects content;
-- is_active is deliberately not overwritten, so an operator who retires a row
-- locally does not have it resurrected by a later re-run.

INSERT INTO regulatory_items
  (code, name, category, jurisdiction, topics, stage, status_summary, key_points,
   next_milestone, next_milestone_date, next_milestone_note,
   confidence, confidence_note, sources, last_verified, display_order)
VALUES
  ('GHGP-CORP', 'GHG Protocol / ISO Consolidated Corporate Standard', 'ghg_accounting', 'Global', ARRAY['climate', 'disclosure']::TEXT[], 'drafting', 'The four GHG Protocol corporate workstreams and ISO 14064-1 are being merged into a single co-branded standard; the separate draft consultations were cancelled in favour of one integrated consultation.', '["Announced 29 July 2026. Builds on the GHGP/ISO strategic partnership of 9 September 2025.", "The separate Corporate Standard and Scope 3 consultation drafts were postponed and folded into a single integrated consultation.", "Approval now needs both GHGP Steering Committee ratification and ISO/TC 207/SC 7 enquiry-stage approval - a new and slower pathway.", "The 2004 Corporate Standard, 2015 Scope 2 Guidance and 2011 Scope 3 Standard remain the operative documents in the meantime. Note: GHGP has not stated this explicitly; it is inferred from the absence of any withdrawal notice."]'::jsonb, 'Integrated public consultation on the consolidated draft', '2027-04-01', 'Estimated Q2 2027; final publication estimated Q4 2028. GHGP states the timeline is subject to change, and it has already slipped once in 2026.', 'confirmed', 'Consolidation decision and dates appear in GHGP’s own Standard Development Plan and press release.', '[{"label": "GHG Protocol - key standard development updates", "url": "https://ghgprotocol.org/blog/ghg-protocol-announces-key-standard-development-updates", "dated": "2026-07-29"}, {"label": "Consolidated Standard Development Plan (PDF)", "url": "https://ghgprotocol.org/sites/default/files/2026-07/Consolidated-StandardDevelopmentPlan(SDP)-2026.07.29.pdf", "dated": "2026-07-29"}, {"label": "ISO and GHG Protocol strategic partnership", "url": "https://ghgprotocol.org/blog/release-iso-and-ghg-protocol-announce-strategic-partnership-deliver-unified-global-standards", "dated": "2025-09-09"}]'::jsonb, '2026-09-04', 10),

  ('GHGP-S2', 'GHG Protocol Scope 2 revision', 'ghg_accounting', 'Global', ARRAY['climate', 'energy']::TEXT[], 'consultation_closed', 'Consultation closed 31 January 2026 with 1,100 responses; the feedback summary published in July 2026 shows genuinely mixed support for the headline hourly-matching and deliverability proposals.', '["Consultation ran 20 October 2025 to 31 January 2026. 1,100 responses from 56 countries.", "The headline proposal was hourly matching and deliverability requirements for market-based reporting, with flexibilities and phased implementation.", "Feedback was contested, not endorsing: objections cited audit burden, conflict with regional frameworks, and infeasibility where hourly data does not exist. Deliverability drew substantial concern.", "No decision has been published. Do not plan on hourly matching being adopted as consulted."]'::jsonb, 'Technical Working Group review of consultation responses', NULL, 'Review began September 2026. No standalone Scope 2 publication - folded into the consolidated Q2 2027 consultation.', 'confirmed', 'Consultation dates, response volume and character of feedback all confirmed from GHGP’s published feedback summary. Any final decision on hourly matching is NOT VERIFIED because none exists.', '[{"label": "Scope 2 public consultation summary of feedback (PDF)", "url": "https://ghgprotocol.org/sites/default/files/2026-07/S2-PublicConsultationSummaryofFeedback-2026.07.29.pdf", "dated": "2026-07-29"}, {"label": "GHG Protocol opens Scope 2 consultation", "url": "https://ghgprotocol.org/blog/release-ghg-protocol-opens-public-consultations-scope-2-and-electricity-sector-consequential", "dated": "2025-10-20"}]'::jsonb, '2026-09-04', 20),

  ('GHGP-S3', 'GHG Protocol Scope 3 revision', 'ghg_accounting', 'Global', ARRAY['climate', 'value_chain']::TEXT[], 'drafting', 'Phase 1 technical proposals published March 2026 signal a substantial tightening of boundary and data-quality rules, with the consultation draft deferred into the consolidated standard.', '["A prescriptive 95% inclusion threshold would replace subjective materiality: at most 5% of Scope 3 may be excluded, and companies must quantify all required emissions to justify an exclusion.", "Emissions would be disaggregated by data type (primary vs secondary), with verification status disclosed and supplier-data allocation restricted to homogeneous suppliers.", "Category 15 narrows to investments only; insurance and underwriting move to a new Category 16. All investments become required and investee Scope 3 comes into the boundary.", "GHGP states explicitly that all of this remains subject to change before any consultation draft."]'::jsonb, 'Consultation draft, via the consolidated standard', '2027-04-01', 'Estimated Q2 2027. No separate Scope 3 date announced.', 'confirmed', 'Confirmed as GHGP’s published Phase 1 proposals. Confidence that they survive unchanged is LOW - GHGP flags them as provisional and the ISO merger adds another revision layer.', '[{"label": "Scope 3 Phase 1 progress update (PDF)", "url": "https://ghgprotocol.org/sites/default/files/2026-03/S3-Phase1ProgressUpdate-20260331.pdf", "dated": "2026-03-31"}]'::jsonb, '2026-09-04', 30),

  ('GHGP-LSR', 'GHG Protocol Land Sector and Removals Standard', 'ghg_accounting', 'Global', ARRAY['climate', 'land', 'value_chain']::TEXT[], 'finalised', 'Final and published, effective 1 January 2027 - the only GHG Protocol item with a near-term binding effective date, and easy to miss amid the consolidation news.', '["Standard v1.0 published 30 January 2026; v1.1 issued June 2026 with minor non-substantive edits. Companion Guidance v1.0 published June 2026.", "Requires accounting for land use change (including deforestation), livestock, fertiliser, rice cultivation, biogenic product emissions and land carbon leakage.", "CO2 removals reporting is optional, subject to integrity safeguards.", "Applies to companies owning or controlling land, or purchasing agricultural products. Builds on rather than replaces the Corporate and Scope 3 Standards."]'::jsonb, 'Effective date', '2027-01-01', 'Separately, a Forest Carbon Accounting Request for Information is open and closes 1 February 2027 - the only open GHGP consultation.', 'confirmed', 'Dates confirmed on GHGP’s own standard page. NOT VERIFIED: whether the effective date refers to reporting periods beginning or ending 1 January 2027 - GHGP does not state transition provisions.', '[{"label": "Land Sector and Removals Standard", "url": "https://ghgprotocol.org/land-sector-and-removals-standard", "dated": "2026-09-04"}, {"label": "What you need to know", "url": "https://ghgprotocol.org/blog/land-sector-and-removals-standard-what-you-need-know", "dated": "2026-01-30"}]'::jsonb, '2026-09-04', 40),

  ('ISO-14064', 'ISO 14064-1 revision and ISO 14068', 'ghg_accounting', 'Global', ARRAY['climate', 'disclosure']::TEXT[], 'drafting', 'ISO 14064-1 is in working draft feeding the joint GHGP standard, while ISO 14068-1:2023 is being replaced by a re-scoped ISO 14068 expected to publish this month.', '["ISO/WD 14064-1.2 reached stage 20.60 (close of comment period) on 12 May 2026. No publication target is stated - consistent with absorption into the Q4 2028 joint standard.", "ISO 14068-1:2023 is at stage 90.92 (to be revised). Its replacement, ISO 14068 (note the dropped part number), was at stage 60.00 (under publication) on 7 August 2026 with edition 1 expected September 2026.", "ISO/TR 14069:2013 was withdrawn on 25 November 2025, revised by ISO/TS 14064-4:2025.", "A joint GHGP/ISO product carbon footprint standard is also in scope of the partnership, but no product-level timeline has been released."]'::jsonb, 'ISO 14068 publication', '2026-09-01', 'Expected September 2026. ISO 14064-1 has no announced date and is expected to land with the joint standard in Q4 2028.', 'confirmed', 'Stage codes and dates are from ISO’s own dated catalogue pages. The inference that 14064-1 lacks a date BECAUSE of the consolidation is not stated by ISO - treat that link as medium.', '[{"label": "ISO/WD 14064-1.2", "url": "https://www.iso.org/standard/90575.html", "dated": "2026-05-12"}, {"label": "ISO 14068 (stage 60.00)", "url": "https://www.iso.org/standard/94470.html", "dated": "2026-08-07"}, {"label": "ISO/TC 207/SC 7 projects under revision", "url": "https://committee.iso.org/sites/tc207sc7/home/projects/ongoing/under-revision.html", "dated": "2026-09-04"}]'::jsonb, '2026-09-04', 50),

  ('SBTI-CNZS2', 'SBTi Corporate Net-Zero Standard V2.0', 'ghg_accounting', 'Global', ARRAY['climate', 'targets']::TEXT[], 'finalised', 'Published and final on 11 June 2026, effective 1 February 2027, with a transition window after which V2.0 becomes mandatory for all target submissions.', '["Scope 1 and Scope 2 targets are now separate rather than combined, each covering 100% of respective emissions.", "Scope 3 moves from fixed 67%/90% coverage thresholds to a significance-based approach: all categories representing 5% or more of categories 1-14 emissions must be covered.", "New target types: asset transition targets (Scope 1), low-carbon electricity alignment targets (Scope 2), and supplier/customer alignment pathways (Scope 3).", "A formal Category A / Category B company split replaces the separate SME route. Removals become mandatory for Category A companies from 2035."]'::jsonb, 'Effective date - validation portal opens for V2.0 submissions', '2027-02-01', 'V2.0 becomes mandatory for all submissions after the transition window closes. SBTi sources give conflicting accounts of the exact V1.3.1 cut-off (“end of 2027” vs “31 January 2028”) - confirm against the validation portal terms before relying on it.', 'confirmed', 'Publication date, effective date and substantive changes all confirmed from SBTi’s own standard PDF and website. The V1.3.1 closure date is MEDIUM because SBTi’s own sources disagree.', '[{"label": "SBTi Corporate Net-Zero Standard V2.0", "url": "https://sciencebasedtargets.org/corporate-net-zero-standard-v2", "dated": "2026-09-04"}, {"label": "SBTi releases CNZS V2.0", "url": "https://sciencebasedtargets.org/news/the-sbti-releases-corporate-net-zero-standard-v2-0-to-accelerate-corporate-climate-action", "dated": "2026-06-11"}, {"label": "Standard V2.0 (PDF)", "url": "https://files.sciencebasedtargets.org/production/files/Corporate-Net-Zero-Standard-version-2.pdf", "dated": "2026-06-11"}]'::jsonb, '2026-09-04', 60),

  ('IFRS-S1S2', 'ISSB - IFRS S1 and IFRS S2', 'ghg_accounting', 'Global', ARRAY['disclosure', 'climate']::TEXT[], 'in_force', 'Both standards remain in force as issued; targeted amendments to S2’s GHG disclosure requirements were finalised in December 2025 and take effect for periods beginning on or after 1 January 2027.', '["The December 2025 amendments give four reliefs: limiting Category 15 to financed emissions; permitting classification systems other than GICS; clarifying partial-entity jurisdictional relief; and relief from using the latest IPCC GWP values.", "Early application of the amendments is permitted. Consequential amendments were made to three SASB Standards.", "More than 40 jurisdictions have adopted or are introducing ISSB Standards (ISSB, March 2026), including Australia, Brazil, Canada, China, Japan, South Korea, Singapore, the UK and the EU.", "A nature-related disclosures Exposure Draft was approved for balloting in July 2026, planned for publication October 2026 with a 120-day comment period. It will supplement rather than amend S1/S2."]'::jsonb, 'S2 amendments effective', '2027-01-01', 'Nature-related disclosures Exposure Draft planned October 2026.', 'confirmed', 'Amendments and dates confirmed from the IFRS Foundation news release and completed-project page. The adoption count is ISSB’s own but dated March 2026, so it may understate the position now.', '[{"label": "ISSB issues targeted amendments to IFRS S2", "url": "https://www.ifrs.org/news-and-events/news/2025/12/issb-issues-targeted-amendments-ifrs-s2/", "dated": "2025-12-11"}, {"label": "Amendments to IFRS S2 (PDF)", "url": "https://www.ifrs.org/content/dam/ifrs/publications/amendments/english/2025/issb-2025-1-amendments-ifrs-s2.pdf", "dated": "2025-12-11"}, {"label": "ISSB Update July 2026", "url": "https://www.ifrs.org/news-and-events/updates/issb/2026/issb-update-july-2026/", "dated": "2026-07-22"}]'::jsonb, '2026-09-04', 70),

  ('CSRD-ESRS', 'CSRD and ESRS (post-Omnibus)', 'eu', 'European Union', ARRAY['disclosure', 'climate']::TEXT[], 'in_force', 'The Omnibus I simplification is final law - Directive (EU) 2026/470, in force 18 March 2026 - cutting CSRD scope sharply, while the revised ESRS delegated act adopted in July 2026 is still in scrutiny.', '["Scope is now >1,000 employees AND >EUR 450m net turnover. Third-country parents: EUR 450m EU turnover with an EU subsidiary or branch above EUR 200m.", "First reporting is for financial years beginning on or after 1 January 2027 (reports published 2028). Non-EU ultimate parents from FY2028.", "Member States MAY exempt former wave 1 companies now out of scope from FY2025 and FY2026 reporting - a national option, so the practical answer differs by country.", "The revised ESRS cut mandatory datapoints by over 60%. Assurance stays at limited; sector-specific ESRS are dropped as mandatory delegated acts."]'::jsonb, 'CSRD transposition deadline', '2027-03-19', 'Before that, the revised ESRS delegated act must clear its scrutiny period and be published in the Official Journal - no date announced. It was still awaiting OJ publication in early September 2026.', 'confirmed', 'CONFIRMED for the directive itself (Official Journal text, Council press release). HIGH for the revised ESRS - adopted by the Commission, but its effective date is contingent on the scrutiny outcome.', '[{"label": "Directive (EU) 2026/470 (EUR-Lex)", "url": "https://eur-lex.europa.eu/eli/dir/2026/470/oj/eng", "dated": "2026-02-26"}, {"label": "Council signs off simplification", "url": "https://www.consilium.europa.eu/en/press/press-releases/2026/02/24/council-signs-off-simplification-of-sustainability-reporting-and-due-diligence-requirements-to-boost-eu-competitiveness/", "dated": "2026-02-24"}, {"label": "Commission adopts revised sustainability reporting standards", "url": "https://finance.ec.europa.eu/news/commission-adopts-revised-sustainability-reporting-standards-2026-07-03_en", "dated": "2026-07-03"}]'::jsonb, '2026-09-04', 100),

  ('CBAM', 'Carbon Border Adjustment Mechanism (CBAM)', 'eu', 'European Union', ARRAY['climate', 'trade', 'value_chain']::TEXT[], 'applying', 'The definitive regime started 1 January 2026 with a 50-tonne de minimis and mandatory authorised-declarant status, but no money changes hands until certificate sales open in February 2027.', '["Sectors: cement, iron and steel, aluminium, fertilisers, electricity, hydrogen.", "A single mass-based de minimis of 50 tonnes per importer per year. Below it there are no CBAM obligations - except hydrogen and electricity importers, who must be authorised regardless of volume.", "The obligation right now is authorisation and data, not payment. Certificates cannot yet be bought.", "From 2027 there is a quarterly holding requirement of 50% of embedded emissions since the start of the year, at four checkpoints."]'::jsonb, 'CBAM certificate sales open', '2027-02-01', 'First annual declaration and certificate surrender for 2026 imports is due 30 September 2027. Separately, a December 2025 proposal would extend CBAM to ~180 downstream steel and aluminium products from 1 January 2028 - PROPOSED ONLY, still with the Council.', 'confirmed', 'CONFIRMED for the definitive regime, threshold and 2027 dates (Commission Q&A and CBAM pages). The downstream extension is explicitly at proposal stage per the Council policy page.', '[{"label": "Commission - CBAM definitive regime", "url": "https://taxation-customs.ec.europa.eu/carbon-border-adjustment-mechanism/cbam-definitive-regime_en", "dated": "2026-09-04"}, {"label": "CBAM Questions and Answers (PDF)", "url": "https://taxation-customs.ec.europa.eu/document/download/013fa763-5dce-4726-a204-69fec04d5ce2_en", "dated": "2026-09-04"}, {"label": "Regulation (EU) 2025/2083 (EUR-Lex)", "url": "https://eur-lex.europa.eu/eli/reg/2025/2083/oj/eng", "dated": "2025-10-08"}]'::jsonb, '2026-09-04', 110),

  ('EUDR', 'EU Deforestation Regulation (EUDR)', 'eu', 'European Union', ARRAY['deforestation', 'value_chain']::TEXT[], 'adopted', 'After a second postponement, obligations bite on 30 December 2026 for large and medium operators - the nearest major deadline on this page - with a July 2026 delegated act trimming product scope still in scrutiny.', '["Application: 30 December 2026 for large and medium operators and traders. 30 June 2027 for other micro and small operators.", "Commodities: cattle, cocoa, coffee, oil palm, rubber, soya and wood, plus derived products. Books, newspapers and printed pictures were removed in the December 2025 revision.", "A delegated act of 13 July 2026 would further remove cattle hides and leather, re-treaded tyres, soybeans for sowing and some rubber articles, and add soluble coffee and certain palm oil derivatives from 30 December 2027. It was in EP/Council scrutiny - treat the carve-outs as likely but not certain.", "Country benchmarking is in force under Implementing Regulation (EU) 2025/1093, with low/standard/high risk tiers. Low-risk sourcing gets simplified due diligence."]'::jsonb, 'Application for large and medium operators', '2026-12-30', 'NOT VERIFIED: whether the July 2026 product-scope delegated act has cleared scrutiny; the specific high-risk and low-risk country lists; and the binding status of the proposed downstream due-diligence-statement simplifications.', 'confirmed', 'CONFIRMED for application dates and delegated act contents (Council press release, Commission newsroom). MEDIUM for the delegated act’s current scrutiny status.', '[{"label": "Council - targeted revision to simplify and postpone", "url": "https://www.consilium.europa.eu/en/press/press-releases/2025/12/18/deforestation-council-signs-off-targeted-revision-to-simplify-and-postpone-the-regulation/", "dated": "2025-12-18"}, {"label": "Commission updates product scope and tools", "url": "https://environment.ec.europa.eu/news/commission-updates-product-scope-and-tools-support-eudr-2026-07-13_en", "dated": "2026-07-13"}, {"label": "Commission EUDR page", "url": "https://environment.ec.europa.eu/topics/forests/deforestation/regulation-deforestation-free-products_en", "dated": "2026-09-04"}]'::jsonb, '2026-09-04', 120),

  ('CSDDD', 'Corporate Sustainability Due Diligence Directive (CSDDD)', 'eu', 'European Union', ARRAY['due_diligence', 'value_chain', 'social']::TEXT[], 'in_force', 'Omnibus I substantially narrowed and softened the CSDDD - scope is now 5,000+ employees and EUR 1.5bn turnover, application is pushed to 2029, and the harmonised civil liability regime and climate transition plan obligation are deleted.', '["Scope: EU companies with >5,000 employees AND >EUR 1.5bn net worldwide turnover. Non-EU: EUR 1.5bn generated in the EU. A dramatic narrowing from the original 1,000 employees / EUR 450m.", "Transposition by 26 July 2028; application unified at 26 July 2029. The original staggered waves are gone.", "The EU harmonised civil liability regime is deleted, and the obligation to adopt and put into effect a climate transition plan is removed.", "Due diligence may prioritise direct business partners. Penalties are capped at 3% of net worldwide turnover."]'::jsonb, 'Commission general due diligence guidelines', '2027-07-26', 'Transposition deadline 26 July 2028; application 26 July 2029.', 'confirmed', 'CONFIRMED from the Official Journal directive and Council press release. The 3% penalty cap is HIGH - stated in the Council release and secondary analysis, but the article text was not read directly.', '[{"label": "Directive (EU) 2026/470 (EUR-Lex)", "url": "https://eur-lex.europa.eu/eli/dir/2026/470/oj/eng", "dated": "2026-02-26"}, {"label": "Council signs off simplification", "url": "https://www.consilium.europa.eu/en/press/press-releases/2026/02/24/council-signs-off-simplification-of-sustainability-reporting-and-due-diligence-requirements-to-boost-eu-competitiveness/", "dated": "2026-02-24"}]'::jsonb, '2026-09-04', 130),

  ('PPWR', 'Packaging and Packaging Waste Regulation (PPWR)', 'eu', 'European Union', ARRAY['packaging', 'chemicals', 'waste']::TEXT[], 'applying', 'Regulation (EU) 2025/40 became generally applicable on 12 August 2026, bringing PFAS limits in food-contact packaging and heavy-metal limits into immediate effect with no transition period.', '["Live now: PFAS restrictions in food-contact packaging at 25 ppb for any individual PFAS and 250 ppb for the sum (targeted analysis, excluding polymeric), plus 50 ppm total PFAS including polymeric.", "Also live: a 100 mg/kg limit on the sum of lead, cadmium, mercury and hexavalent chromium.", "There is no transition period - packaging manufactured before 12 August but first placed on the market after must comply.", "Harmonised labelling is NOT yet live: it applies from the later of 12 August 2028 or 24 months after the relevant implementing acts."]'::jsonb, 'Main design obligations - recycled content, design for recycling, single-use bans', '2030-01-01', 'Then 2035 (recycled-at-scale criteria), 2038 (minimum grade B) and 2040 (higher recycled content). Waste reduction targets: 5% per capita by 2030, 10% by 2035, 15% by 2040 against 2018.', 'confirmed', 'CONFIRMED for entry into force and the 12 August 2026 application date (Commission page states both). HIGH for the PFAS thresholds - specialist and law-firm sources; the article text could not be extracted from EUR-Lex directly, so confirm the numbers against the OJ before relying on them.', '[{"label": "Commission - packaging waste", "url": "https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en", "dated": "2026-09-04"}, {"label": "PPWR PFAS limits apply from August 12", "url": "https://foodpackagingforum.org/news/ppwr-pfas-limits-apply-from-august-12", "dated": "2026-08-12"}]'::jsonb, '2026-09-04', 140),

  ('EU-PFAS', 'EU universal PFAS restriction (REACH)', 'eu', 'European Union', ARRAY['chemicals']::TEXT[], 'in_negotiation', 'RAC adopted its final opinion in March 2026 and SEAC agreed a draft, but SEAC’s final opinion is only expected by end-2026 - no universal PFAS restriction is in law and none will be for some time.', '["Nothing is binding yet. This remains a restriction proposal from Denmark, Germany, the Netherlands, Norway and Sweden. Do not treat any PFAS ban date as fixed.", "RAC’s final opinion (2 March 2026) favoured the strictest option on pure risk grounds - a full ban with an 18-month transition.", "SEAC’s draft opinion (10 March 2026) provisionally favours a ban with use-specific, mostly time-limited derogations, while stating overall proportionality cannot be confirmed given data gaps.", "The near-term PFAS compliance exposure comes from PPWR food-contact packaging limits, live since 12 August 2026 - not from this restriction."]'::jsonb, 'SEAC final opinion', NULL, 'Expected by end of 2026, no specific date announced. Then the Commission must draft a restriction for REACH Committee vote and EP/Council scrutiny - realistically 2027 at the earliest.', 'high', 'HIGH for the RAC/SEAC opinion dates and status. LOW for any timeline beyond SEAC’s final opinion - genuinely unannounced. ECHA’s own site blocked direct fetching, so this is via a verbatim reproduction and law-firm analyses.', '[{"label": "ECHA - PFAS restriction: Committees’ opinions and next steps", "url": "https://www.echa.europa.eu/-/pfas-2026-echa-committees-opinions", "dated": "2026-03-26"}, {"label": "CMS - what happens next", "url": "https://cms.law/en/deu/legal-updates/support-for-eu-wide-pfas-restriction-with-targeted-derogations-what-happens-next", "dated": "2026-03-26"}]'::jsonb, '2026-09-04', 150),

  ('EU-TAXONOMY', 'EU Taxonomy (simplified)', 'eu', 'European Union', ARRAY['disclosure', 'climate']::TEXT[], 'applying', 'Unlike the rest of the Omnibus package the Taxonomy simplification is already done and applying - Delegated Regulation (EU) 2026/73 applies from 1 January 2026 with a 10% materiality threshold.', '["Published in the OJ 8 January 2026, in force 28 January 2026, applying from 1 January 2026.", "Activities cumulatively representing less than 10% of turnover (and equivalently CapEx/OpEx) need not be assessed for alignment.", "Reporting templates cut sharply - roughly 64% fewer datapoints for non-financial undertakings and 89% fewer for financial undertakings.", "Scope follows CSRD, so the Omnibus narrowing carries across to Article 8 Taxonomy reporting."]'::jsonb, 'Revised technical screening criteria and DNSH requirements', '2027-01-01', 'Targeted for 1 January 2027 application - PROPOSED, not adopted.', 'confirmed', 'CONFIRMED for the delegated regulation, its dates and the 10% threshold. MEDIUM for the datapoint-reduction percentages. NOT VERIFIED: whether a formal voluntary opt-in exists for out-of-scope companies - sources conflict, so the tool asserts neither.', '[{"label": "Delegated Regulation (EU) 2026/73 published in the OJ", "url": "https://sustainablefutures.linklaters.com/post/102m1i3/eu-delegated-act-on-simplifying-taxonomy-reporting-published-in-the-official-jou", "dated": "2026-01-09"}, {"label": "EU Taxonomy Delegated Act enters into force", "url": "https://www.hsfkramer.com/notes/esg/2026-posts/omnibus-update-eu-taxonomy-delegated-act-enters-into-force", "dated": "2026-01-28"}]'::jsonb, '2026-09-04', 160),

  ('CA-SB253', 'California SB 253 - Climate Corporate Data Accountability Act', 'us', 'United States - California', ARRAY['climate', 'disclosure']::TEXT[], 'in_force', 'In force and not enjoined, with the first Scope 1 and 2 reports due 10 November 2026 - but the implementing regulation was still awaiting OAL approval as of early August 2026.', '["Threshold: US-formed entities with >USD 1bn total annual revenue doing business in California. Applicability is per entity, without affiliate aggregation, and intercompany revenue is excluded.", "The deadline moved from 10 August to 10 November 2026. Any cached “August 10” date is wrong.", "No assurance is required for the 2026 report. Limited assurance over Scope 1 and 2 begins with 2027 reports, escalating to reasonable assurance by 2030.", "Substantial first-year relief: entities may submit emissions information in their possession as of 5 December 2024, and CARB will exercise enforcement discretion for good-faith submissions. Scope 3 is not required until 2027, then only five categories."]'::jsonb, 'First Scope 1 and 2 reports due', '2026-11-10', 'NOT VERIFIED as of the last check: whether OAL has approved the modified regulation (comment period closed 11 August 2026), and whether CARB’s guidance and online intake platform launched as planned on 1 September 2026.', 'high', 'HIGH - multiple independent law-firm reports of CARB’s own rulemaking documents, mutually consistent. MEDIUM on current OAL status because the newest source is several weeks old. One source (KPMG) implied assurance in 2026; two more specific sources place it in 2027 - verify against CARB’s regulation text.', '[{"label": "Mayer Brown - CARB finalizes initial rulemaking, resets the 2026 deadline", "url": "https://www.mayerbrown.com/en/insights/publications/2026/08/california-climate-disclosure-laws-carb-finalizes-its-initial-rulemaking-resets-the-2026-deadline-and-previews-the-2027-framework", "dated": "2026-08-05"}, {"label": "Morgan Lewis - CARB extends SB 253 deadline", "url": "https://www.morganlewis.com/pubs/2026/08/carb-extends-sb-253-deadline-and-previews-2027-reporting-rules", "dated": "2026-08-07"}, {"label": "Debevoise - CARB clarifies initial SB 253 regulations", "url": "https://www.debevoise.com/insights/publications/2026/08/carb-clarifies-initial-sb-253-regulations", "dated": "2026-08-07"}]'::jsonb, '2026-09-04', 200),

  ('CA-SB261', 'California SB 261 - Climate-Related Financial Risk Report', 'us', 'United States - California', ARRAY['climate', 'disclosure']::TEXT[], 'enjoined', 'Enjoined - the Ninth Circuit blocked enforcement in November 2025 and CARB has formally said it will not enforce the 1 January 2026 deadline, so reports are not currently due.', '["Threshold: entities with >USD 500m total annual revenue doing business in California. Biennial report aligned to the 2017 TCFD recommendations.", "The injunction is specific to SB 261. The same Ninth Circuit order DENIED an injunction as to SB 253, which continues to operate. Do not conflate the two.", "CARB’s enforcement advisory of 1 December 2025 confirms it will not enforce against entities that miss the statutory deadline, and that it will announce an alternate date after the appeal resolves.", "Voluntary filing is happening anyway - CARB reported over 120 reports publicly submitted. The statute is paused, not struck down."]'::jsonb, 'Ninth Circuit merits decision in Chamber of Commerce v. Sanchez', NULL, 'Argued 9 January 2026, no decision date announced. This is the most volatile item on this page and the fastest to go stale.', 'confirmed', 'CONFIRMED for the injunction and CARB non-enforcement (court order plus CARB’s own advisory). MEDIUM on “still pending” - re-check the docket before relying on it.', '[{"label": "Chamber of Commerce v. CARB - docket", "url": "https://www.climatecasechart.com/collections/chamber-of-commerce-of-the-united-states-of-america-v-california-air-resources-board_a046f8", "dated": "2026-09-04"}, {"label": "Ninth Circuit grants injunction pending appeal", "url": "https://corpgov.law.harvard.edu/2025/12/03/california-climate-disclosure-law-sb-261-implementation-halted-ninth-circuit-grants-injunction-pending-appeal/", "dated": "2025-12-03"}]'::jsonb, '2026-09-04', 210),

  ('SEC-CLIMATE', 'SEC climate disclosure rule', 'us', 'United States - Federal', ARRAY['climate', 'disclosure']::TEXT[], 'stayed', 'Effectively dead - stayed since April 2024, undefended by the Commission since March 2025, and formally proposed for full rescission in June 2026, with nothing replacing it.', '["The March 2024 final rules were stayed by the SEC itself on 4 April 2024 and have never taken effect. No company has ever had to comply.", "The rules were NOT judicially vacated. The Eighth Circuit held the petitions in abeyance after the Commission ended its defence. “Struck down by the Eighth Circuit” is a common and incorrect framing.", "A rescission proposal (Release Nos. 33-11421 / 34-105572) was published in the Federal Register on 3 June 2026; the comment period closed 3 August 2026.", "Nothing replaced it. For US-listed companies the binding pressure now comes from California, the EU CSRD, and existing SEC materiality principles."]'::jsonb, 'Final rescission action', NULL, 'No date announced. NOT VERIFIED whether the SEC has adopted a final rescission since the comment period closed.', 'confirmed', 'CONFIRMED for the proposal, stay and abeyance (Federal Register text and the SEC’s own release). MEDIUM on whether final action has occurred very recently.', '[{"label": "Federal Register - Rescission of Climate-Related Disclosure Rules", "url": "https://www.federalregister.gov/documents/2026/06/03/2026-11091/rescission-of-climate-related-disclosure-rules", "dated": "2026-06-03"}, {"label": "SEC press release 2026-49", "url": "https://www.sec.gov/newsroom/press-releases/2026-49-sec-proposes-rescission-climate-related-disclosure-rules", "dated": "2026-06-03"}]'::jsonb, '2026-09-04', 220),

  ('EPA-PFAS-TSCA', 'EPA PFAS reporting - TSCA Section 8(a)(7)', 'us', 'United States - Federal', ARRAY['chemicals']::TEXT[], 'in_force', 'In force as a rule but the submission window has been repeatedly postponed; reporting now starts no later than 31 January 2027, and possibly earlier, while a significant scope-narrowing revision is pending.', '["The submission period begins 31 January 2027, OR 60 days after a date to be set in a future Federal Register notice, whichever is earlier. It is a conditional trigger, not a fixed date.", "EPA’s own program page still displays the superseded 13 October 2026 deadline. Use the Federal Register rule, not the program page.", "Scope as written is very broad: anyone who manufactured or imported PFAS or PFAS-containing articles since 1 January 2011 must report, covering at least 1,462 listed PFAS, with a 2011-2022 lookback.", "A November 2025 proposal would exempt PFAS in mixtures at 0.1% or less, imported articles, and certain byproducts and R&D substances - removing many downstream importers from scope. Not final."]'::jsonb, 'EPA final revision rule', NULL, 'No date announced; EPA said “later this year” (2026). Backstop reporting start is 31 January 2027.', 'confirmed', 'CONFIRMED for the timing mechanism (Federal Register final rule of 13 April 2026). The conflict between EPA’s two pages is a documented fact, not an inference.', '[{"label": "Federal Register - modification to the start of the submission period", "url": "https://www.federalregister.gov/documents/2026/04/13/2026-07062/modification-to-the-start-of-the-submission-period-for-perfluoroalkyl-and-polyfluoroalkyl-substances", "dated": "2026-04-13"}, {"label": "EPA - update to reporting deadline", "url": "https://www.epa.gov/chemicals-under-tsca/update-reporting-deadline-tsca-pfas-reporting-rule", "dated": "2026-04-09"}]'::jsonb, '2026-09-04', 230),

  ('EPA-PFAS-NPDWR', 'EPA PFAS drinking water standards', 'us', 'United States - Federal', ARRAY['chemicals', 'water']::TEXT[], 'in_force', 'The April 2024 standards remain legally in force for all six PFAS, but EPA has proposed to rescind four of them and to extend PFOA/PFOS compliance from 2029 to 2031; neither proposal is final.', '["Currently enforceable: PFOA and PFOS at 4.0 ppt each; PFHxS, PFNA and HFPO-DA (GenX) at 10 ppt each; and a Hazard Index of 1 for mixtures. Compliance deadline 2029, initial monitoring due 2027.", "A proposed rescission (May 2026) would eliminate the standards for PFHxS, PFNA, GenX and the Hazard Index - four of the six - leaving only PFOA and PFOS.", "A separate proposal would let systems request two extra years, moving PFOA/PFOS compliance from 2029 to 2031.", "Practical read: plan against all six and the 2029 date for now, but the four non-PFOA/PFOS limits are at real risk and timing may slip."]'::jsonb, 'Final action on either proposal', NULL, 'No date announced; both comment periods closed 20 July 2026.', 'confirmed', 'CONFIRMED - EPA’s own Safe Drinking Water Act pages, updated May to July 2026, plus Federal Register publication.', '[{"label": "EPA - PFAS drinking water", "url": "https://www.epa.gov/sdwa/and-polyfluoroalkyl-substances-pfas", "dated": "2026-05-18"}, {"label": "EPA - proposed PFAS rescission rule", "url": "https://www.epa.gov/sdwa/proposed-pfas-rescission-rule", "dated": "2026-07-23"}]'::jsonb, '2026-09-04', 240),

  ('EPA-GHGRP', 'EPA Greenhouse Gas Reporting Program (GHGRP)', 'us', 'United States - Federal', ARRAY['climate', 'disclosure']::TEXT[], 'in_force', 'Still in force and reporting is still required, but EPA has proposed to repeal nearly all of it, and the 2025 reporting-year deadline was pushed to 30 October 2026 to buy time for that decision.', '["The RY2025 deadline moved from 31 March to 30 October 2026 by final rule. Reporters must still file.", "The repeal proposal would rescind reporting for 46 source categories, retaining only subpart W (petroleum and natural gas systems) minus gas distribution - and suspending even those until reporting year 2034.", "Not finalised. EPA said it anticipates addressing the remainder of the proposal in one or more subsequent final actions.", "States are expanding their own GHG reporting to fill the federal gap, so facility-level obligations may migrate rather than vanish."]'::jsonb, 'RY2025 reporting deadline', '2026-10-30', 'Final action on the repeal - no date announced.', 'confirmed', 'CONFIRMED for the deadline extension and the proposal contents (Federal Register text for both). MEDIUM that no final repeal has issued very recently.', '[{"label": "Federal Register - extending the RY2025 reporting deadline", "url": "https://www.federalregister.gov/documents/2026/02/27/2026-03995/extending-the-reporting-deadline-under-the-greenhouse-gas-reporting-rule-for-2025", "dated": "2026-02-27"}, {"label": "Federal Register - reconsideration of the GHGRP", "url": "https://www.federalregister.gov/documents/2025/09/16/2025-17923/reconsideration-of-the-greenhouse-gas-reporting-program", "dated": "2025-09-16"}]'::jsonb, '2026-09-04', 250),

  ('US-STATES', 'US state climate disclosure laws beyond California', 'us', 'United States - States', ARRAY['climate', 'disclosure']::TEXT[], 'proposed', 'California remains the only state with enacted enterprise-level climate disclosure law; every other state proposal checked is pending or dead, though New York has a separate facility-level GHG reporting rule that is final.', '["New York S3456 is pending, not law - it never passed either chamber. Related bills S9072A and S3697A failed before the session ended 4 June 2026.", "New York 6 NYCRR Part 253 IS final (1 December 2025) - but it is facility-level GHG reporting, not corporate disclosure. The numeric collision with California SB 253 is a real trap.", "Colorado HB25-1119 was postponed indefinitely. New Jersey S4117 and Illinois HB3673 were pending as of the last verified source.", "Proposals are converging on a USD 1bn revenue threshold modelled on California, so California readiness is largely portable."]'::jsonb, 'New York Part 253 first annual reports', '2027-06-01', '2027 state legislative sessions - no dates announced.', 'medium', 'MEDIUM overall. CONFIRMED for New York S3456 (the Senate’s own bill record) and HIGH for Part 253. The Colorado, New Jersey and Illinois statuses come from an April 2025 source that is now stale - their 2026-session outcomes are NOT VERIFIED. No Washington enterprise-level bill was found either way.', '[{"label": "New York Senate - S3456 bill record", "url": "https://www.nysenate.gov/legislation/bills/2025/S3456", "dated": "2026-09-04"}, {"label": "Beveridge & Diamond - states expand GHG reporting", "url": "https://www.bdlaw.com/publications/with-federal-greenhouse-gas-reporting-in-limbo-states-expand-ghg-reporting/", "dated": "2026-07-09"}]'::jsonb, '2026-09-04', 260)

